const locationId = 'Zwz4relUXVPxx8uohnjV';
const apiKey = 'pit-a55a45b3-f933-4898-9cbb-7cfe74c95d28';
const baseUrl = 'https://services.leadconnectorhq.com';
const baselineWebhookUrl = 'https://automations.livetransparent.com/webhook/ghl-mql-opportunity-baseline-v2';
const pageSize = 100;

const headers = {
  Authorization: `Bearer ${apiKey}`,
  Version: '2021-07-28',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP not available in Code node runtime.');
}

const matched = [];
let totalScanned = 0;
let startAfter;
let startAfterId;

for (let page = 1; page <= 1000; page += 1) {
  let url = `${baseUrl}/contacts/?locationId=${encodeURIComponent(locationId)}&limit=${pageSize}`;
  if (startAfter !== undefined && startAfterId) {
    url += `&startAfter=${encodeURIComponent(startAfter)}&startAfterId=${encodeURIComponent(startAfterId)}`;
  }

  const data = await doHttpRequest.call(this, {
    method: 'GET',
    url,
    headers,
    json: true,
  });

  const contacts = Array.isArray(data?.contacts) ? data.contacts : [];
  totalScanned += contacts.length;

  for (const contact of contacts) {
    const tags = Array.isArray(contact?.tags) ? contact.tags : [];
    if (tags.some((tag) => String(tag).trim().toLowerCase() === 'mql')) {
      matched.push({
        contactId: contact.id || '',
        contactName: contact.contactName || [contact.firstName, contact.lastName].filter(Boolean).join(' ').trim() || `Contact ${contact.id || ''}`,
      });
    }
  }

  const meta = data?.meta || {};
  if (!meta.nextPageUrl || !meta.startAfterId) break;
  startAfter = meta.startAfter;
  startAfterId = meta.startAfterId;
}

let processed = 0;
const errors = [];

for (const contact of matched) {
  try {
    await doHttpRequest.call(this, {
      method: 'POST',
      url: baselineWebhookUrl,
      headers: {
        'Content-Type': 'application/json',
      },
      body: {
        contactId: contact.contactId,
        contactName: contact.contactName,
        tag: 'mql',
      },
      json: true,
    });
    processed += 1;
  } catch (err) {
    errors.push({
      contactId: contact.contactId,
      message: err?.message || String(err),
    });
  }
}

return [{
  json: {
    status: errors.length ? 'completed_with_errors' : 'completed',
    totalScanned,
    matchedMqlContacts: matched.length,
    processed,
    errorCount: errors.length,
    errors,
  },
}];
